def is_flow_set_schedulable(flow_set_F):
    for flow_i in flow_set_F:
        if not is_flow_schedulable(flow_i, flow_i.response_time, flow_i.D):
            return False
    return True

def calculate_blocking_delay(flow_i, blocking_flow_set_i, flit_tx_time):
    B_i = 0
    for link_L in flow_i.route:
        max_blocking_on_link = 0
        for flow_p in blocking_flow_set_i:
            if link_L in flow_p.route:
                # In flit-level preemption, delta_p is flit_tx_time
                max_blocking_on_link = max(max_blocking_on_link, flit_tx_time) 
        B_i += max_blocking_on_link
    return B_i

def calculate_num_instances(busy_period_i, T_i):
    K_i = math.floor(busy_period_i / T_i)
    return K_i

def calculate_finish_time_instance(flow_i, k, B_i, C_i, direct_interference_flow_set_i):
    finish_time_i_k_current = B_i + k * C_i
    while True:
        interference = calculate_interference_delay(flow_i, finish_time_i_k_current, direct_interference_flow_set_i)
        finish_time_i_k_next = B_i + k * C_i + interference
        if finish_time_i_k_next == finish_time_i_k_current:
            return finish_time_i_k_next
        finish_time_i_k_current = finish_time_i_k_next

def calculate_preemptive_part_busy_period(flow_i, k, B_i, C_i, response_time_non_preemptive_i, direct_interference_flow_set_i):
    busy_period_preemptive_part_i_k_current = B_i + k * C_i - response_time_non_preemptive_i
    while True:
        interference = calculate_interference_delay(flow_i, busy_period_preemptive_part_i_k_current, direct_interference_flow_set_i)
        busy_period_preemptive_part_i_k_next = B_i + k * C_i - response_time_non_preemptive_i + interference
        if busy_period_preemptive_part_i_k_next == busy_period_preemptive_part_i_k_current:
            return busy_period_preemptive_part_i_k_next
        busy_period_preemptive_part_i_k_current = busy_period_preemptive_part_i_k_next

def calculate_total_response_time_instance_npe(S_npe_i_k, k, T_i, response_time_non_preemptive_i):
    response_time_i_k = (S_npe_i_k - (k - 1) * T_i) + response_time_non_preemptive_i
    return response_time_i_k

def calculate_critical_instants_set(k, T_i, D_i, response_time_non_preemptive_i, direct_interference_flow_set_i):
    start_window = (k - 1) * T_i
    end_window = (k - 1) * T_i + D_i - response_time_non_preemptive_i

    critical_instants = set()
    critical_instants.add(end_window) # Add the deadline itself

    for flow_j in direct_interference_flow_set_i:
        # Iterate through possible instances 'p' of flow_j
        # A more robust implementation would iterate 'p' until release time exceeds end_window
        for p in range(1, int(math.ceil((end_window + flow_j.interference_jitter) / flow_j.T)) + 2): # +2 for safety margin
            release_time_j_p = max(0, (p - 1) * flow_j.T - flow_j.interference_jitter)
            if start_window <= release_time_j_p <= end_window:
                critical_instants.add(release_time_j_p)
            elif release_time_j_p > end_window:
                break # No more instances of flow_j will fall in the window

    return sorted(list(critical_instants))

def is_flow_schedulable_theorem_2(flow_i, K_i, B_i, C_i, response_time_non_preemptive_i, direct_interference_flow_set_i, D_i, T_i):
    for k in range(1, K_i + 1):
        critical_instants = calculate_critical_instants_set(k, T_i, D_i, response_time_non_preemptive_i, direct_interference_flow_set_i)
        instance_k_schedulable = False
        for t in critical_instants:
            workload = B_i + k * C_i - response_time_non_preemptive_i + calculate_interference_delay(flow_i, t, direct_interference_flow_set_i)
            if workload <= t:
                instance_k_schedulable = True
                break
        if not instance_k_schedulable:
            return False # Instance k misses its deadline
    return True # All instances are schedulable

def calculate_overall_blocking_tolerance(flow_i, K_i, C_i, response_time_non_preemptive_i, direct_interference_flow_set_i, D_i, T_i):
    min_blocking_tolerance = float('inf') # Initialize with a very large number

    for k in range(1, K_i + 1):
        blocking_tolerance_k = calculate_blocking_tolerance_instance(flow_i, k, C_i, response_time_non_preemptive_i, direct_interference_flow_set_i, D_i, T_i)
        min_blocking_tolerance = min(min_blocking_tolerance, blocking_tolerance_k)

    return min_blocking_tolerance

def calculate_blocking_links_set(flow_i, blocking_flow_set_i):
    blocking_links_set_i = set()
    for flow_j in blocking_flow_set_i:
        common_links = set(flow_i.route).intersection(set(flow_j.route))
        blocking_links_set_i.update(common_links)
    return blocking_links_set_i

def calculate_blocking_tolerance_per_link_edbt(blocking_tolerance_i, blocking_links_set_i):
    num_blocking_links_i = len(blocking_links_set_i)
    return blocking_tolerance_i / max(1, num_blocking_links_i)

def select_non_preemptive_region_length_hpdbt(flow_i, max_packet_tx_time_per_link_i, direct_interference_flow_set_i, all_flows_blocking_info):
    min_allowed_blocking_from_hp_flows = float('inf')

    for flow_j in direct_interference_flow_set_i:
        common_links = set(flow_i.route).intersection(set(flow_j.route))
        num_common_links = len(common_links)

        if num_common_links == 0:
            continue # No shared links, no blocking caused by flow_i to flow_j on these links

        for link_l in common_links:
            # all_flows_blocking_info[flow_j.id] contains { 'beta_minus': ..., 'beta_l': {link_id: val, ...}}
            beta_minus_j = all_flows_blocking_info[flow_j.id]['beta_minus']
            beta_j_l = all_flows_blocking_info[flow_j.id]['beta_l'].get(link_l, 0) # Default to 0 if not assigned

            # This is the available blocking tolerance on link_l for flow_j
            effective_tolerance_on_link_l = (beta_minus_j / num_common_links) + beta_j_l
            min_allowed_blocking_from_hp_flows = min(min_allowed_blocking_from_hp_flows, effective_tolerance_on_link_l)

    non_preemptive_region_tx_time_per_link_i = min(max_packet_tx_time_per_link_i, min_allowed_blocking_from_hp_flows)
    return non_preemptive_region_tx_time_per_link_i
